{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Spiramycin, the closest retrieved analogue (Morgan 0.3077), has absolute oral bioavailability of 33% in healthy volunteers after a 1 g oral dose, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Clarithromycin, a macrolide with a dimethylamino sugar, has absolute oral bioavailability of 55% at 500 mg in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Erythromycin base has absolute bioavailability of approximately 40% after oral dosing in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Rosaramicin, a 16-membered macrolide, has absolute bioavailability of 39% after a 500 mg oral tablet in men, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "14-OH-clarithromycin, an active macrolide metabolite, has oral bioavailability of 35% in healthy adults, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Dirithromycin, a macrolide prodrug, has absolute oral bioavailability of about 10%, below the 20% threshold; its lower similarity and distinct prodrug structure limit transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C39"],
      "claim": "EM574, an erythromycin-derived macrolide, has estimated oral bioavailability of about 2%, below threshold; it is structurally distinct and less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a macrolide antibiotic with a dimethylamino sugar and a poly-O-methyl sugar. The closest analogue spiramycin has F 33-39%; other macrolides (erythromycin, clarithromycin, rosaramicin, 14-OH-clarithromycin) have F 25-55%, all above 20%. Low-F analogues (dirithromycin, EM574) are less similar and structurally distinct. Overall evidence supports F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule.",
    "Morgan similarities to evidence molecules are low (<0.31), limiting quantitative transfer.",
    "Differences in sugar substitution and macrocycle oxidation may alter first-pass metabolism and absorption.",
    "Some macrolides (dirithromycin, EM574) show low F, indicating class-level variability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

